const CORRIDOR_ALIASES: Record<string, string> = {
  "hà nội_lào cai": "hanoi_laocai",
  "ha noi_lao cai": "hanoi_laocai",
  "hanoi_sapa": "hanoi_laocai",
  "hà nội_sa pa": "hanoi_laocai",
  "hanoi_laocai": "hanoi_laocai",
  "đà nẵng_huế": "danang_hue",
  "da nang_hue": "danang_hue",
  "đà nẵng_thừa thiên huế": "danang_hue",
  "da nang_thua thien hue": "danang_hue",
  "danang_hue": "danang_hue",
  "hồ chí minh_đà lạt": "hcm_dalat",
  "ho chi minh_da lat": "hcm_dalat",
  "hồ chí minh_lâm đồng": "hcm_dalat",
  "tp. hồ chí minh_lâm đồng": "hcm_dalat",
  "hcm_dalat": "hcm_dalat",
  "hồ chí minh_bà rịa - vũng tàu": "hcm_vungtau",
  "ho chi minh_vung tau": "hcm_vungtau",
  "tp. hồ chí minh_vũng tàu": "hcm_vungtau",
  "hồ chí minh_vũng tàu": "hcm_vungtau",
  "hcm_vungtau": "hcm_vungtau",
  "hà nội_hải phòng": "hanoi_haiphong",
  "ha noi_hai phong": "hanoi_haiphong",
  "hanoi_haiphong": "hanoi_haiphong"
};

export function getPrecalculatedCorridor(originNorm: string, destNorm: string): PrecalculatedCorridorRoutes | null {
  const norm1 = originNorm.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").replace(/\s+/g, "").trim();
  const norm2 = destNorm.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").replace(/\s+/g, "").trim();

  for (const [alias, targetKey] of Object.entries(CORRIDOR_ALIASES)) {
    const aliasClean = alias.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").trim();
    const parts = aliasClean.split("_");
    if (parts.length >= 2 && parts[0] && parts[1]) {
      const fromPart = parts[0].replace(/\s+/g, "");
      const toPart = parts[1].replace(/\s+/g, "");

      const isForward = (norm1.includes(fromPart) || fromPart.includes(norm1)) && (norm2.includes(toPart) || toPart.includes(norm2));
      if (isForward && PRECALCULATED_CORRIDORS[targetKey]) {
        return PRECALCULATED_CORRIDORS[targetKey]!;
      }

      const isReverse = (norm1.includes(toPart) || toPart.includes(norm1)) && (norm2.includes(fromPart) || fromPart.includes(norm2));
      if (isReverse && PRECALCULATED_CORRIDORS[targetKey]) {
        const orig = PRECALCULATED_CORRIDORS[targetKey]!;
        return {
          weather_safer: { ...orig.weather_safer, coordinates: [...orig.weather_safer.coordinates].reverse() },
          fastest: { ...orig.fastest, coordinates: [...orig.fastest.coordinates].reverse() },
          shortest: { ...orig.shortest, coordinates: [...orig.shortest.coordinates].reverse() },
        };
      }
    }
  }
  return null;
}
